//! SC-007: a deliberate 100 Hz shift of a band edge toward the band is caught by both the
//! response check and the golden check (spec 004 tasks.md T024; research R-06). Three fixtures,
//! generated by `tools/filter-design/design_voiceband.py --shift-*`: the record high-pass up
//! 100 Hz, the record low-pass stopband edge down 100 Hz, the playback low-pass down 100 Hz.

#[path = "fixtures/shifted_playback_lp_down100.rs"]
mod playback_lp;
#[path = "fixtures/shifted_record_hp_up100.rs"]
mod record_hp;
#[path = "fixtures/shifted_record_lp_down100.rs"]
mod record_lp;

use rr_dr60::{Pipeline, Settings};
use rr_dr60_harness::checks::{self, Stage};
use rr_dr60_harness::golden;

fn record_hp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        record_hp::SHIFTED_RECORD_SOS,
        record_hp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn record_lp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        record_lp::SHIFTED_RECORD_SOS,
        record_lp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn playback_lp_mutant(s: Settings) -> Pipeline {
    Pipeline::__with_stage_sos(
        s,
        playback_lp::SHIFTED_RECORD_SOS,
        playback_lp::SHIFTED_PLAYBACK_SOS,
    )
    .unwrap()
}

fn failed_properties(results: &[rr_dr60_harness::checks::MeasurementResult]) -> Vec<&'static str> {
    results
        .iter()
        .filter(|r| !r.passed)
        .map(|r| r.property)
        .collect()
}

/// Spec 004 SC-007 (research R-06): each toward-band shift fails its stage's template on the
/// row the shift moves. The record high-pass up 100 Hz breaks the 225–2250 Hz loss maximum;
/// a low-pass stopband edge down 100 Hz breaks the loss at 2550 Hz (about 9–11 dB).
#[test]
fn record_hp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Record,
        &record_hp_mutant,
    ));
    assert!(
        failed.contains(&"loss 225-2250 Hz (max)"),
        "record high-pass shift not caught; failures: {failed:?}"
    );
}

#[test]
fn record_lp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Record,
        &record_lp_mutant,
    ));
    assert!(
        failed.contains(&"loss at 2550 Hz"),
        "record low-pass shift not caught; failures: {failed:?}"
    );
}

#[test]
fn playback_lp_shift_is_caught() {
    let failed = failed_properties(&checks::check_stage_template(
        48_000,
        Stage::Playback,
        &playback_lp_mutant,
    ));
    assert!(
        failed.contains(&"loss at 2550 Hz"),
        "playback low-pass shift not caught; failures: {failed:?}"
    );
}

/// Spec 004 SC-007: each mutant also fails the spec 001 golden check against the committed
/// file, which is the 6 kHz re-bless of T038 (the unmutated pipeline matches it, see
/// `tests/golden.rs`), so a failure here means the mutation changed the output, not the rate.
#[test]
fn golden_check_catches_shifted_band_edges() {
    let expected = golden::committed();
    for (name, mutant) in [
        ("record hp", record_hp_mutant as fn(Settings) -> Pipeline),
        ("record lp", record_lp_mutant),
        ("playback lp", playback_lp_mutant),
    ] {
        let actual = golden::generate(&mutant);
        let report = golden::compare(&expected, &actual).expect_err(name);
        assert!(
            report.contains("sweep_log/default/48000 Hz differs"),
            "{name}: {report}"
        );
    }
}

/// Spec 005 SC-007 (T035): a deliberate doubling of the default release, or a 3 dB shift of
/// the knee, is caught by both a tolerance check and the AGC golden check. The mutants are
/// built through the harness's `Make` factory with altered public settings (005 research R-08);
/// the plan's `__with_limiter_mutation` hook was not needed and was not kept
/// (contracts/rust-api.md › Test hooks).
mod agc {
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::agc_checks;
    use rr_dr60_harness::golden;

    fn release_x2(mut s: Settings) -> Pipeline {
        s.agc.release_ms *= 2.0; // engineering target (005 SC-007)
        Pipeline::new(s).unwrap()
    }

    /// −3 dB (the default is −1 dBFS; +3 would also be in range since the knee moved, but −3
    /// stays the mutant the golden file was blessed against).
    fn knee_minus_3(mut s: Settings) -> Pipeline {
        s.agc.knee_dbfs -= 3.0; // engineering target (005 SC-007)
        Pipeline::new(s).unwrap()
    }

    fn failed_properties(
        results: &[rr_dr60_harness::checks::MeasurementResult],
    ) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    #[test]
    fn release_change_is_caught() {
        // The FR-006 −1 dB release-time row: 2.72 s against 0.82–1.92 s.
        let failed = failed_properties(&agc_checks::check_fr006_release(48_000, &release_x2));
        assert!(
            failed.contains(&"release time to -1 dB"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(&golden::committed_agc(), &golden::generate_agc(&release_x2));
        assert!(diff.is_err(), "AGC golden check missed the release change");
    }

    #[test]
    fn knee_change_is_caught() {
        // The ceiling rows cannot catch a knee shift (the ceiling is derived from the bisected
        // knee); the knee row does (005 T035).
        let failed = failed_properties(&agc_checks::check_fr004_static(48_000, &knee_minus_3));
        assert!(
            failed.contains(&"knee (-1 dB gain point) by bisection"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(
            &golden::committed_agc(),
            &golden::generate_agc(&knee_minus_3),
        );
        assert!(diff.is_err(), "AGC golden check missed the knee change");
    }
}

/// Spec 003 SC-007, kept by spec 005 SC-007 (T035): a deliberate change of the default hang
/// time by 20 %, or of the threshold by 3 dB (−40 → −37 dBFS since spec 005, A-022 revised),
/// is caught by both a tolerance check and the VAS golden check. The mutants are built through
/// the harness's `Make` factory with altered public settings, with no hidden hooks.
mod vas {
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::golden;
    use rr_dr60_harness::vas_checks;

    fn hang_x1_2(mut s: Settings) -> Pipeline {
        s.vas.hang_ms *= 1.2; // 20 %, engineering target (003 FR-017; SC-007)
        Pipeline::new(s).unwrap()
    }

    fn threshold_plus_3(mut s: Settings) -> Pipeline {
        s.vas.threshold_dbfs += 3.0; // 3 dB, engineering target (003 FR-017; SC-007)
        Pipeline::new(s).unwrap()
    }

    fn failed_properties(
        results: &[rr_dr60_harness::checks::MeasurementResult],
    ) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    #[test]
    fn hang_change_is_caught() {
        let defaults = vas_checks::matrix()[0];
        let failed =
            failed_properties(&vas_checks::check_fr008_hang(48_000, &defaults, &hang_x1_2));
        assert!(
            failed.contains(&"kept part of the gap"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(&golden::committed_vas(), &golden::generate_vas(&hang_x1_2));
        assert!(diff.is_err(), "VAS golden check missed the hang change");
    }

    #[test]
    fn threshold_change_is_caught() {
        let defaults = vas_checks::matrix()[0];
        let failed = failed_properties(&vas_checks::check_fr006_threshold(
            48_000,
            &defaults,
            &threshold_plus_3,
        ));
        assert!(
            failed.contains(&"threshold at 1 kHz − nominal"),
            "not caught; failures: {failed:?}"
        );
        let diff = golden::compare(
            &golden::committed_vas(),
            &golden::generate_vas(&threshold_plus_3),
        );
        assert!(
            diff.is_err(),
            "VAS golden check missed the threshold change"
        );
    }
}

/// Spec 006 SC-002, SC-004 (T039): the two harness-side split mutants (research R-08) against
/// the golden equivalence: a recording missing its first stored sample no longer reproduces
/// the golden entry's SHA-256, and a flipped CRC bit is refused at import. The mutants are
/// transforms of exported bytes (`split_checks::mutants`), never in the core; `us3_export_import`
/// proves the same two mutants fail the round-trip check.
mod split {
    use rr_dr60::Pipeline;
    use rr_dr60_harness::split_checks::{self, mutants};
    use rr_dr60_harness::{configs, golden};

    /// The `tone_1k_m20` / `default` golden entry at 48 kHz, recorded, exported, mutated,
    /// imported into a fresh engine and played: its SHA-256 differs from the entry's.
    #[test]
    fn drop_first_sample_breaks_the_golden_equivalence() {
        let a = golden::applicable_entries()
            .into_iter()
            .find(|a| {
                a.stimulus == "tone_1k_m20" && a.config == "default" && a.host_rate_hz == 48_000
            })
            .expect("entry");
        let x = golden::stimulus(a.stimulus, 48_000);
        let mut p = Pipeline::new(a.settings).unwrap();
        p.start_recording().unwrap();
        let _ = p.record(&x, &mut []).unwrap();
        let _ = p.stop_recording(&mut []).unwrap();
        let bytes = split_checks::export_bytes(&p, 1);
        let n = a.entry.n_samples as usize;
        // Healthy: reproduced.
        let mut healthy = Pipeline::new(a.settings).unwrap();
        assert_eq!(healthy.import(&bytes), Ok(1));
        let out = split_checks::play_to_end(&mut healthy, 1, 997);
        let pre = &out[..out.len() - healthy.drain_samples() as usize];
        assert_eq!(
            golden::entry(a.stimulus, a.config, 48_000, &pre[..n]).sha256,
            a.entry.sha256
        );
        // Mutant: caught.
        let mut mutant = Pipeline::new(a.settings).unwrap();
        assert_eq!(mutant.import(&mutants::drop_first_sample(&bytes)), Ok(1));
        let out = split_checks::play_to_end(&mut mutant, 1, 997);
        let pre = &out[..out.len() - mutant.drain_samples() as usize];
        assert!(
            pre.len() < n
                || golden::entry(a.stimulus, a.config, 48_000, &pre[..n]).sha256 != a.entry.sha256
        );
    }

    /// A flipped CRC bit never reaches the memory.
    #[test]
    fn crc_bit_flip_is_refused() {
        let mut p = Pipeline::new(configs::settings("default_agc", 48_000)).unwrap();
        p.start_recording().unwrap();
        let _ = p
            .record(&golden::stimulus("tone_1k_m20", 48_000), &mut [])
            .unwrap();
        let _ = p.stop_recording(&mut []).unwrap();
        let bytes = split_checks::export_bytes(&p, 1);
        let before = p.memory_status();
        assert_eq!(
            p.import(&mutants::flip_crc_bit(&bytes)),
            Err(rr_dr60::Error::Damaged)
        );
        assert_eq!(p.memory_status(), before);
        assert_eq!(p.import(&bytes), Ok(2));
    }
}

/// Spec 008 SC-008 (T022): a one-bit change in a stored frame changes the playback output; an
/// input change after frame k's look-ahead leaves frame k's bytes unchanged (and one inside it
/// changes them); and a wrong codec delay would fail the one-pass equivalence: the comparison
/// shifted by one device sample's worth fails where the right skip passes.
mod codec {
    use rr_dr60::{__test_hooks, Pipeline, StopResult};
    use rr_dr60_harness::stimulus::voiced;
    use rr_dr60_harness::{codec_checks, configs, split_checks};

    fn record(p: &mut Pipeline, x: &[f32]) -> u32 {
        p.start_recording().unwrap();
        let _ = p.record(x, &mut []).unwrap();
        match p.stop_recording(&mut []).unwrap().result {
            StopResult::Kept { number, .. } => number,
            other => panic!("{other:?}"),
        }
    }

    #[test]
    fn one_bit_change_in_a_stored_frame_changes_the_playback() {
        let s = configs::memory_capacity(configs::settings("codec_only", 6000), 10, 2);
        let x = voiced(6000.0, 1.0, -20.0, 0x0D60);
        let mut healthy = Pipeline::new(s).unwrap();
        let n = record(&mut healthy, &x);
        let want = split_checks::play_to_end(&mut healthy, n, 997);
        let mut mutant = healthy.clone();
        // Byte 23, bit 5: inside frame 2's lag code.
        assert!(__test_hooks::flip_stored_frame_bit(&mut mutant, n, 23, 5));
        assert_ne!(
            __test_hooks::stored_frames(&mutant, n),
            __test_hooks::stored_frames(&healthy, n)
        );
        let got = split_checks::play_to_end(&mut mutant, n, 997);
        assert_eq!(got.len(), want.len());
        assert_ne!(got, want, "a flipped frame bit must change the sound");
        // Frames before the flipped one play the same (the decoder is causal).
        assert_eq!(got[..240], want[..240]);
    }

    #[test]
    fn input_change_after_the_lookahead_leaves_the_frame_bytes_unchanged() {
        let s = configs::memory_capacity(configs::settings("codec_only", 6000), 10, 2);
        let x = voiced(6000.0, 1.0, -20.0, 0x0D60);
        let k = 3usize;
        let bytes_of = |y: &[f32]| {
            let mut p = Pipeline::new(s).unwrap();
            let n = record(&mut p, y);
            __test_hooks::stored_frames(&p, n).to_vec()
        };
        let base = bytes_of(&x);
        // Offsets 60 and beyond leave frame k unchanged (asserted); a step from the frame's
        // own first sample changes it (asserted); a step at the look-ahead's last sample is
        // reported only: the analysis window's weight there is small and a one-sample change
        // often flips no 3-bit index (spec 008 plan review P5).
        for (offset, expect) in [
            (60usize, Some(true)),
            (120, Some(true)),
            (0, Some(false)),
            (59, None),
            (30, None),
        ] {
            let mut y = x.clone();
            for v in y.iter_mut().skip(120 * (k + 1) + offset) {
                *v = 0.9;
            }
            let got = bytes_of(&y);
            let frame = 10 * k..10 * (k + 1);
            assert_eq!(
                got[..10 * k],
                base[..10 * k],
                "frames before {k} at offset {offset}"
            );
            let same = got[frame.clone()] == base[frame];
            match expect {
                Some(want) => assert_eq!(same, want, "frame {k} at offset {offset}"),
                None => println!(
                    "frame {k}: a full-scale step at look-ahead offset {offset} {} its bytes",
                    if same { "leaves" } else { "changes" }
                ),
            }
        }
    }

    #[test]
    fn a_wrong_delay_would_fail_the_one_pass_equivalence() {
        let rate = 48_000;
        let s = configs::settings("codec_only", rate);
        let x = voiced(f64::from(rate), 1.0, -20.0, 0x0D60);
        let mut p = Pipeline::new(s).unwrap();
        let run = split_checks::record_then_play(&mut p, &x, 4801, 997);
        let d = codec_checks::delay_host(rate);
        let per_device = split_checks::host_per_device(rate);
        // Two device samples' worth of extra tail, so the shifted comparisons stay in range.
        let tail = p.record_latency_samples() as usize - d
            + (run.stop.silence_fed_samples as usize + 120 + 2) * per_device;
        let mut y = x.clone();
        y.extend(std::iter::repeat_n(0.0f32, tail));
        let mut one = Pipeline::new(s).unwrap();
        let mut out = vec![0.0f32; y.len()];
        let _ = one.process(&y, &mut out).unwrap();
        let n = run.pre_drain.len();
        let same = |skip: usize| out[skip..skip + n] == run.pre_drain[..];
        assert!(same(d), "the right skip passes");
        assert!(!same(d + per_device), "one device sample too late fails");
        assert!(!same(d - per_device), "one device sample too early fails");
    }
}

/// Spec 009 SC-006 (tasks.md T017): a deliberate alteration of the output chain, applied
/// through `Pipeline::__with_output_mutation` (never by editing the generated table), is caught
/// by the named check: the speaker template's numerator 2 % high by the peak-gain row; a knee
/// starting at 0.5 by the distortion bracket; the drain's settle 100 samples short by the drain
/// table; the speaker route's gain 10 % high by the THD at the reference position.
mod output {
    use rr_dr60::__test_hooks::OutputMutation;
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::checks::MeasurementResult;
    use rr_dr60_harness::output_checks;

    fn failed(results: &[MeasurementResult]) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    fn mutant(m: OutputMutation) -> impl Fn(Settings) -> Pipeline {
        move |s| Pipeline::__with_output_mutation(s, &m).unwrap()
    }

    /// Spec 010 FR-007 (tasks.md T016; research R-06): a bound at 0.5, a bound at 1 + 2⁻²³
    /// and positive-only bounding each fail the identity check on the full-scale square in
    /// `output_only_speaker_clamp` at 48 kHz; the committed bound passes it.
    #[test]
    fn output_clamp_mutants_are_caught_by_the_identity() {
        use rr_dr60::Route;
        use rr_dr60_harness::output_clamp_checks::{Expect, identity_at};
        let rows = |make: &dyn Fn(Settings) -> Pipeline| {
            identity_at(
                make,
                48_000,
                "output_only_speaker_clamp",
                Route::Speaker,
                1.0,
                "square_1k_fs",
                1.0,
                Expect::Exceeds,
            )
        };
        for (name, m) in [
            (
                "bound 0.5",
                OutputMutation {
                    clamp_bound: 0.5,
                    ..OutputMutation::default()
                },
            ),
            (
                "bound 1 + 2^-23",
                OutputMutation {
                    clamp_bound: 1.0 + f64::from(f32::EPSILON), // 2⁻²³
                    ..OutputMutation::default()
                },
            ),
            (
                "positive only",
                OutputMutation {
                    clamp_positive_only: true,
                    ..OutputMutation::default()
                },
            ),
        ] {
            let f = failed(&rows(&mutant(m)));
            assert!(f.iter().any(|p| p.starts_with("identity")), "{name}: {f:?}");
        }
        assert!(failed(&rows(&rr_dr60_harness::checks::standard)).is_empty());
    }

    #[test]
    fn speaker_numerator_scale_is_caught_by_the_peak_gain_row() {
        let make = mutant(OutputMutation {
            speaker_numerator_scale: 1.02,
            ..OutputMutation::default()
        });
        let f = failed(&output_checks::speaker_response(48_000, &make));
        assert!(f.iter().any(|p| p.contains("never above 1.0")), "{f:?}");
        // The committed chain passes the same rows.
        assert!(
            failed(&output_checks::speaker_response(
                48_000,
                &rr_dr60_harness::checks::standard
            ))
            .is_empty()
        );
    }

    /// A knee starting at 0.5 softens the curve: the compression at the ceiling rises to
    /// 1 − 0.5 / 4 = 0.875 (1.16 dB, above FR-006's 1 dB), while the 10 % THD crossing stays
    /// inside +1 … +3 dB (the task's 0.95 start sits inside every bracket, so the softer knee
    /// is the honest mutant; coach review T019).
    #[test]
    fn soft_knee_is_caught_by_the_distortion_bracket() {
        let make = mutant(OutputMutation {
            knee_start: 0.5,
            ..OutputMutation::default()
        });
        let f = failed(&output_checks::clip(48_000, &make));
        assert!(f.iter().any(|p| p.contains("compression")), "{f:?}");
    }

    #[test]
    fn short_settle_is_caught_by_the_drain_table() {
        // The growth rows (the literal N_OUT table) catch a one-sample change; the ring-down
        // row needs a large cut: at N_OUT the earphone route's tail reads about −152 dBFS at
        // 6 kHz (the 32 Hz state after a 1 kHz tone sits 30 dB below the tone and decays
        // 100 dB; the follower's corners attenuate the slow tail further), so the −80 dBFS
        // bound has about 70 dB of margin. 280 samples short of the 346 (−80 %), at
        // 0.29 dB per sample, lifts the tail by about 81 dB and trips the row.
        let make = mutant(OutputMutation {
            n_out_delta: -280,
            ..OutputMutation::default()
        });
        let f = failed(&output_checks::chain_drain_table(6000, &make));
        assert!(f.iter().any(|p| p.contains("last 1 ms")), "{f:?}");
        assert!(
            f.iter().any(|p| p.contains("minus the bypassed drain")),
            "{f:?}"
        );
    }

    #[test]
    fn gain_scale_is_caught_by_the_reference_position_thd() {
        let make = mutant(OutputMutation {
            gain_scale: 1.1,
            ..OutputMutation::default()
        });
        let f = failed(&output_checks::default_position_level(48_000, &make));
        assert!(
            f.iter()
                .any(|p| p.contains("THD at the reference position")),
            "{f:?}"
        );
    }

    /// Spec 011 research R-07 (tasks.md T023): the four volume-transition mutant
    /// configurations, applied through the test hooks, are each caught by the named row at
    /// 48 kHz on the earphone route; the committed chain passes the same rows.
    mod volume_ramp {
        use super::{failed, mutant};
        use rr_dr60::__test_hooks::OutputMutation;
        use rr_dr60_harness::checks::standard;
        use rr_dr60_harness::volume_ramp_checks as ramp;

        const RATE: u32 = 48_000;
        const CONFIG: &str = "stage11_only_earphone";

        #[test]
        fn volume_ramp_step_mutant_fails_fr004_and_the_last_differing_sample() {
            let make = mutant(OutputMutation {
                volume_step: true,
                ..OutputMutation::default()
            });
            let f = failed(&ramp::click_reduction(&make, RATE, CONFIG, 0.1, 1.0));
            assert!(f.iter().any(|p| p.contains("instantaneous step")), "{f:?}");
            let f = failed(&ramp::splice(&make, RATE, CONFIG, 0.1, 1.0));
            assert!(
                f.iter().any(|p| p.contains("last transition sample")),
                "{f:?}"
            );
            assert!(failed(&ramp::click_reduction(&standard, RATE, CONFIG, 0.1, 1.0)).is_empty());
        }

        #[test]
        fn volume_ramp_linear_mutant_fails_fr004_on_the_speaker_law() {
            let make = mutant(OutputMutation {
                volume_shape_linear: true,
                ..OutputMutation::default()
            });
            let f = failed(&ramp::click_reduction(
                &make,
                RATE,
                "stage11_only_speaker",
                0.1,
                1.0,
            ));
            assert!(f.iter().any(|p| p.contains("instantaneous step")), "{f:?}");
        }

        #[test]
        fn volume_ramp_length_mutants_fail_the_splice() {
            for (delta, row) in [
                (1i64, "from transition sample N"),
                (-1, "last transition sample"),
            ] {
                let make = mutant(OutputMutation {
                    volume_ramp_delta: delta,
                    ..OutputMutation::default()
                });
                let f = failed(&ramp::splice(&make, RATE, CONFIG, 0.1, 1.0));
                assert!(f.iter().any(|p| p.contains(row)), "{delta:+}: {f:?}");
            }
            assert!(failed(&ramp::splice(&standard, RATE, CONFIG, 0.1, 1.0)).is_empty());
        }
    }
}

/// Spec 012 (tasks.md T038; research R-11): the five microphone-path mutants each fail their
/// row at 48 kHz, and the committed path passes the same rows: the input high-pass removed
/// fails the band; a symmetric or a polarity-swapped clipper fails the static curve's limits;
/// a stream shared by every recording fails the counters' cross-correlation; the hiss 3 dB high
/// fails the hiss level.
mod mic {
    use rr_dr60::__test_hooks::MicMutation;
    use rr_dr60::{Pipeline, Settings};
    use rr_dr60_harness::checks::{MeasurementResult, standard};
    use rr_dr60_harness::mic_checks as mic;

    const RATE: u32 = 48_000;

    fn failed(results: &[MeasurementResult]) -> Vec<&'static str> {
        results
            .iter()
            .filter(|r| !r.passed)
            .map(|r| r.property)
            .collect()
    }

    fn mutant(m: MicMutation) -> impl Fn(Settings) -> Pipeline {
        move |s| Pipeline::__with_mic_mutation(s, &m).unwrap()
    }

    #[test]
    fn no_input_hp_fails_the_band() {
        let make = mutant(MicMutation {
            no_input_hp: true,
            ..MicMutation::default()
        });
        let f = failed(&mic::band(&make, RATE));
        assert!(f.contains(&"deviation from the prototype"), "{f:?}");
        assert!(failed(&mic::band(&standard, RATE)).is_empty());
    }

    #[test]
    fn symmetric_clip_fails_the_static_curve() {
        let make = mutant(MicMutation {
            symmetric_clip: true,
            ..MicMutation::default()
        });
        let f = failed(&mic::static_curve(&make, RATE));
        assert!(f.contains(&"largest output re L+ (clipper units)"), "{f:?}");
        assert!(failed(&mic::static_curve(&standard, RATE)).is_empty());
    }

    #[test]
    fn swapped_polarity_fails_the_static_curve() {
        let make = mutant(MicMutation {
            swapped_polarity: true,
            ..MicMutation::default()
        });
        let f = failed(&mic::static_curve(&make, RATE));
        assert!(f.contains(&"largest output re L+ (clipper units)"), "{f:?}");
        assert!(
            f.contains(&"smallest output re -L- (clipper units)"),
            "{f:?}"
        );
    }

    /// Hardware review B4: a knee moved by ±0.05 (both polarities) fails the static curve's
    /// onset rows in clipper units, which the engine-input tolerance alone would pass.
    #[test]
    fn knee_moved_fails_the_static_curve() {
        for delta in [-0.05f32, 0.05] {
            let make = mutant(MicMutation {
                knee_delta: delta,
                ..MicMutation::default()
            });
            let f = failed(&mic::static_curve(&make, RATE));
            assert!(f.contains(&"positive onset re L+"), "{delta}: {f:?}");
            assert!(f.contains(&"negative onset re L-"), "{delta}: {f:?}");
        }
    }

    #[test]
    fn shared_stream_fails_the_counters_cross_correlation() {
        let make = mutant(MicMutation {
            shared_stream: true,
            ..MicMutation::default()
        });
        let f = failed(&mic::streams(&make, RATE));
        assert!(
            f.contains(&"normalized cross-correlation at lag 0, x sqrt(N)"),
            "{f:?}"
        );
        assert!(failed(&mic::streams(&standard, RATE)).is_empty());
    }

    #[test]
    fn hiss_3_db_high_fails_the_hiss_level() {
        let make = mutant(MicMutation {
            hiss_db_delta: 3.0,
            ..MicMutation::default()
        });
        let f = failed(&mic::hiss_level(&make, RATE, 0.0));
        assert!(
            f.contains(&"hiss level, 300-3000 Hz (AES17) re the figure + offset"),
            "{f:?}"
        );
        assert!(failed(&mic::hiss_level(&standard, RATE, 0.0)).is_empty());
    }
}

